import cadquery as cq

plate = cq.Solid.makeBox(80, 50, 2, cq.Vector(-40, -25, 0))

vent_boxes = []
for cx in [-28, -20, -12, -4, 4, 12, 20, 28]:
    for cy in [-16, -8, 0, 8, 16]:
        vent = cq.Solid.makeBox(4, 4, 4, cq.Vector(cx - 2, cy - 2, -1))
        vent_boxes.append(vent)

vent_cutter = vent_boxes[0]
for v in vent_boxes[1:]:
    vent_cutter = vent_cutter.fuse(v)

hole_cylinders = []
for sx in [36, -36]:
    for sy in [21, -21]:
        hole = cq.Solid.makeCylinder(1.5, 4, cq.Vector(sx, sy, -1), cq.Vector(0, 0, 1))
        hole_cylinders.append(hole)

hole_cutter = hole_cylinders[0]
for h in hole_cylinders[1:]:
    hole_cutter = hole_cutter.fuse(h)

cutter = vent_cutter.fuse(hole_cutter)
result = plate.cut(cutter)

